+import { check } from "recheck";
+import { expect, test } from "vitest";
+import * as z from "zod/v4";
+
+const r = z.core.regexes;
+const bools = [true, false];
+const precisions = [null, -1, 0, 3, 6];
+
+const patterns: Record<string, RegExp> = {
+  ...Object.fromEntries(Object.entries(r).filter(([, v]) => v instanceof RegExp)),
+  emoji: r.emoji(),
+  mac: r.mac(),
+  "mac-": r.mac("-"),
+  uuid: r.uuid(),
+  string: r.string(),
+  "string{2,5}": r.string({ minimum: 2, maximum: 5 }),
+};
+for (let v = 1; v <= 8; v++) patterns[`uuid${v}`] = r.uuid(v);
+for (const precision of precisions) {
+  patterns[`time(${precision})`] = r.time({ precision });
+  for (const local of bools)
+    for (const offset of bools)
+      patterns[`datetime(${precision},${local},${offset})`] = r.datetime({ precision, local, offset });
+}
+
+test("emoji regex shape", () => {
+  const re = r.emoji();
+  expect(re.flags).toBe("u");
+  expect(re.source).toBe("^[\\p{Extended_Pictographic}\\p{Emoji_Component}]+$");
+});
+
+test.each(Object.entries(patterns))("no super-linear backtracking: %s", async (_, re) => {
+  const result = await check(re.source, re.flags);
+  expect(result.status).not.toBe("vulnerable");
+});

